def scorer(text, anchor, params):
    import re
    import math

    similarity_threshold = params.get('similarity_threshold', 0.3)
    ideal_length = params.get('ideal_length', 80)
    length_sensitivity = params.get('length_sensitivity', 0.015)

    def simple_token_overlap(t1, t2):
        stopwords = set(['the','a','an','is','are','was','were','be','been',
                         'have','has','had','do','does','did','will','would',
                         'to','of','in','for','on','with','at','by','from',
                         'as','it','this','that','and','or','but','not','i',
                         'we','you','he','she','they','my','your','our'])
        def get_tokens(s):
            return set(w for w in re.findall(r'\b[a-zA-Z]+\b', s.lower())
                       if w not in stopwords)
        t1_tokens = get_tokens(t1)
        t2_tokens = get_tokens(t2)
        if not t1_tokens or not t2_tokens:
            return 0.0
        intersection = t1_tokens & t2_tokens
        union = t1_tokens | t2_tokens
        return len(intersection) / len(union)

    if not anchor or not anchor.strip():
        # No anchor: fall back to pure brevity scoring
        words = re.findall(r'\b[a-zA-Z]+\b', text)
        num_words = len(words)
        if num_words == 0:
            return 0.0
        brevity_score = math.exp(-length_sensitivity * max(0, num_words - ideal_length))
        return float(min(1.0, brevity_score))

    semantic_sim = simple_token_overlap(text, anchor)

    # Gate: if semantic similarity below threshold, conciseness is penalized
    if semantic_sim < similarity_threshold:
        gate = semantic_sim / similarity_threshold
    else:
        gate = 1.0

    words = re.findall(r'\b[a-zA-Z]+\b', text)
    num_words = len(words)
    if num_words == 0:
        return 0.0

    brevity_score = math.exp(-length_sensitivity * max(0, num_words - ideal_length))

    # Also penalize extremely short texts (< 5 words) as likely incomplete
    if num_words < 5:
        brevity_score *= (num_words / 5.0)

    score = gate * brevity_score
    score = max(0.0, min(1.0, score))
    return float(score)

