def scorer(text, anchor, params):
    import re
    import math

    # --- Input validation / smoke-test guard ---
    try:
        if not isinstance(text, str) or not isinstance(anchor, str):
            return 0.0
        text = text.strip()
        anchor = anchor.strip()
        if len(text) == 0 or len(anchor) == 0:
            return 0.0
    except Exception:
        return 0.0

    # --- Parameters ---
    alpha = float(params.get('alpha', 0.5)) if params else 0.5

    STOPWORDS = {
        'a','an','the','and','or','but','in','on','at','to','for','of','with',
        'is','are','was','were','be','been','being','have','has','had','do',
        'does','did','will','would','could','should','may','might','shall',
        'that','this','these','those','it','its','i','you','he','she','we',
        'they','their','them','our','your','my','his','her','not','no','so',
        'as','by','from','up','out','if','about','into','than','then','there'
    }

    def compute_conciseness(t):
        try:
            words = re.findall(r'[a-zA-Z]+', t.lower())
            if len(words) == 0:
                return 0.5  # neutral fallback
            content_words = [w for w in words if w not in STOPWORDS]
            unique_content = set(content_words)
            total = len(words)
            unique_c = max(len(unique_content), 1)
            # verbosity ratio: higher means more filler relative to content
            verbosity = total / unique_c
            # conciseness score in [0, 1]
            score = 1.0 / (1.0 + alpha * max(verbosity - 1.0, 0.0))
            return float(score)
        except Exception:
            return 0.0

    try:
        score_text = compute_conciseness(text)
        score_anchor = compute_conciseness(anchor)
        # Return relative conciseness: how much more concise text is vs anchor
        delta = score_text - score_anchor
        # Normalize to [0, 1] range
        final_score = (delta + 1.0) / 2.0
        return float(max(0.0, min(1.0, final_score)))
    except Exception:
        return 0.0
